#!/usr/bin/env python3
"""Emit PSI gauges and cumulative totals for inventoried cgroup v2 paths."""
import json
import os
import re
import time
from pathlib import Path, PurePosixPath

SCHEMA_VERSION = 1
COLLECTOR = "linux_cgroup_psi_v1"
CGROUP_ROOT = Path("/sys/fs/cgroup")
APP_ROOT = Path(__file__).resolve().parents[1]
TARGETS_FILE = APP_ROOT / "local" / "psi-cgroups.json"
TARGET_RE = re.compile(r"^[A-Za-z0-9_.@:-]{1,64}$")
RESOURCES = ("cpu", "memory", "io")


def emit(status, kind, **fields):
    event = {
        "schema_version": SCHEMA_VERSION,
        "collector": COLLECTOR,
        "collector_status": status,
        "event_kind": kind,
        "sample_epoch": SAMPLE_EPOCH,
    }
    event.update(fields)
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


def parse_flat(path):
    values = {}
    for line in path.read_text(encoding="ascii").splitlines():
        parts = line.split()
        if len(parts) != 2:
            raise ValueError("invalid_flat_file")
        values[parts[0]] = parts[1]
    return values


def parse_pressure(path):
    lanes = {}
    for line in path.read_text(encoding="ascii").splitlines():
        parts = line.split()
        if len(parts) != 5 or parts[0] not in ("some", "full"):
            raise ValueError("invalid_pressure_line")
        fields = {}
        for token in parts[1:]:
            key, separator, value = token.partition("=")
            if not separator or key in fields:
                raise ValueError("invalid_pressure_field")
            fields[key] = value
        if set(fields) != {"avg10", "avg60", "avg300", "total"}:
            raise ValueError("incomplete_pressure_fields")
        parsed = {
            "avg10_pct": float(fields["avg10"]),
            "avg60_pct": float(fields["avg60"]),
            "avg300_pct": float(fields["avg300"]),
            "total_stall_usec": int(fields["total"]),
        }
        if any(parsed[name] < 0 or parsed[name] > 100 for name in ("avg10_pct", "avg60_pct", "avg300_pct")) or parsed["total_stall_usec"] < 0:
            raise ValueError("pressure_value_out_of_range")
        lanes[parts[0]] = parsed
    if not lanes:
        raise ValueError("no_pressure_lanes")
    return lanes


def load_targets():
    payload = json.loads(TARGETS_FILE.read_text(encoding="utf-8"))
    targets = payload.get("targets")
    if not isinstance(targets, list) or not targets or len(targets) > 256:
        raise ValueError("invalid_targets")
    normalized = []
    seen_names = set()
    seen_paths = set()
    for item in targets:
        if not isinstance(item, dict) or set(item) != {"target_name", "cgroup_path"}:
            raise ValueError("invalid_target")
        target_name = item["target_name"]
        raw_path = item["cgroup_path"]
        if not isinstance(target_name, str) or not TARGET_RE.fullmatch(target_name):
            raise ValueError("invalid_target_name")
        if not isinstance(raw_path, str) or not raw_path.startswith("/") or "\n" in raw_path:
            raise ValueError("invalid_cgroup_path")
        logical_path = PurePosixPath(raw_path)
        if ".." in logical_path.parts or str(logical_path) == "/":
            raise ValueError("unsafe_or_root_cgroup_path")
        canonical_path = "/" + "/".join(logical_path.parts[1:])
        if target_name in seen_names or canonical_path in seen_paths:
            raise ValueError("duplicate_target")
        seen_names.add(target_name)
        seen_paths.add(canonical_path)
        normalized.append((target_name, canonical_path, CGROUP_ROOT.joinpath(*logical_path.parts[1:])))
    return normalized


SAMPLE_EPOCH = int(time.time())
try:
    if not (CGROUP_ROOT / "cgroup.controllers").is_file():
        raise ValueError("cgroup_v2_not_mounted")
    BOOT_ID = Path("/proc/sys/kernel/random/boot_id").read_text(encoding="ascii").strip()
    TARGETS = load_targets()
    if not BOOT_ID:
        raise ValueError("empty_boot_id")
except (OSError, ValueError, json.JSONDecodeError) as error:
    emit("configuration_error", "collector", error_type=type(error).__name__)
    raise SystemExit(0)

for target_name, cgroup_path, directory in TARGETS:
    common = {"boot_id": BOOT_ID, "target_name": target_name, "cgroup_path": cgroup_path}
    errors = []
    emitted_lanes = 0
    try:
        cgroup_inode = os.stat(directory, follow_symlinks=False).st_ino
        events = parse_flat(directory / "cgroup.events")
        populated = int(events["populated"])
        pressure_control = directory / "cgroup.pressure"
        if pressure_control.is_file():
            psi_accounting_state = "enabled" if pressure_control.read_text(encoding="ascii").strip() == "1" else "disabled"
        else:
            psi_accounting_state = "not_exposed"
        identity = {"cgroup_inode": cgroup_inode, "populated": populated, "psi_accounting_state": psi_accounting_state}
        for resource in RESOURCES:
            try:
                for scope, fields in parse_pressure(directory / f"{resource}.pressure").items():
                    emit("ok", "pressure", **common, **identity, resource=resource, scope=scope, **fields)
                    emitted_lanes += 1
            except (OSError, UnicodeError, ValueError) as error:
                errors.append(f"{resource}:{type(error).__name__}")
        emit("ok" if not errors else "partial", "target_summary", **common, **identity, emitted_lanes=emitted_lanes, errors=errors)
    except (OSError, KeyError, UnicodeError, ValueError) as error:
        emit("read_error", "target_summary", **common, error_type=type(error).__name__, emitted_lanes=emitted_lanes, errors=errors)
